import{bt as e,n as t,ot as n,st as r}from"./chunks/framework.CxhjsvYc.js";var i=JSON.parse(`{"title":"Web UI, UX and accessibility audit","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/WEB-UI-UX-ACCESSIBILITY.html"}],["meta",{"property":"og:title","content":"Web UI, UX and accessibility audit | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/WEB-UI-UX-ACCESSIBILITY.html"}],["meta",{"name":"twitter:title","content":"Web UI, UX and accessibility audit | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"audits/WEB-UI-UX-ACCESSIBILITY.md","filePath":"audits/WEB-UI-UX-ACCESSIBILITY.md","lastUpdated":1794198491000}`),a={name:`audits/WEB-UI-UX-ACCESSIBILITY.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="web-ui-ux-and-accessibility-audit" tabindex="-1">Web UI, UX and accessibility audit <a class="header-anchor" href="#web-ui-ux-and-accessibility-audit" aria-label="Permalink to “Web UI, UX and accessibility audit”">​</a></h1><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>Reviewed the browser form structure, account and cash-flow editors, strategy controls, status/error feedback, responsive CSS, motion helpers, focus/error handling, and the web rules in RULESETS.</p><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to “Findings”">​</a></h2><h3 id="ui-01-—-programmatic-scrolling-and-reduced-motion-preference" tabindex="-1">UI-01 — Programmatic scrolling and reduced-motion preference <a class="header-anchor" href="#ui-01-—-programmatic-scrolling-and-reduced-motion-preference" aria-label="Permalink to “UI-01 — Programmatic scrolling and reduced-motion preference”">​</a></h3><p><strong>Current status: IMPLEMENTED on this branch; CI passed.</strong> Validation errors, general error feedback and result navigation use the shared <code>scrollElementIntoView()</code> helper in <code>src/web/motion.js</code>. It checks <code>prefers-reduced-motion</code> at the time of each request, selects <code>behavior: &quot;auto&quot;</code> for reduced-motion users, and preserves smooth scrolling for other users. The existing reduced-motion CSS rule forces computed <code>scroll-behavior: auto</code>.</p><p><strong>Regression coverage:</strong> <code>tests/js/motion-guidelines.test.js</code> verifies both preference branches and confirms the app no longer calls smooth <code>scrollIntoView()</code> directly.</p><h3 id="ui-02-—-help-tooltip-content-and-touch-operation" tabindex="-1">UI-02 — Help tooltip content and touch operation <a class="header-anchor" href="#ui-02-—-help-tooltip-content-and-touch-operation" aria-label="Permalink to “UI-02 — Help tooltip content and touch operation”">​</a></h3><p><strong>Current status: IMPLEMENTED on this branch; CI passed.</strong> Static and dynamically rendered help markers are native <code>button type=&quot;button&quot;</code> controls. Their accessible names contain the full help explanation, and <code>aria-expanded</code> exposes the disclosure state. Pointer hover and keyboard focus retain the visual tooltip; clicking/tapping toggles it, clicking elsewhere closes it, and Escape dismisses the open tooltip. The focus-visible indicator is retained.</p><p><strong>Regression coverage:</strong> <code>tests/js/web-controls-contract.test.js</code> checks native button semantics, accessible naming, expanded-state handling, Escape dismissal and the CSS disclosure state.</p><p><strong>Verification boundary:</strong> the Node contract suite does not replace manual keyboard, touch-device or screen-reader verification. Those remain part of browser QA.</p><h3 id="ui-03-—-inline-validation-messages-and-field-association" tabindex="-1">UI-03 — Inline validation messages and field association <a class="header-anchor" href="#ui-03-—-inline-validation-messages-and-field-association" aria-label="Permalink to “UI-03 — Inline validation messages and field association”">​</a></h3><p><strong>Current status: IMPLEMENTED on this branch; CI passed.</strong> <code>markField()</code> now assigns each generated error message a unique ID and adds that ID to the invalid control&#39;s <code>aria-describedby</code>. <code>clearFieldErrors()</code> removes only generated error IDs from existing description lists, preserving unrelated descriptions, then removes the visual error and <code>aria-invalid</code> state.</p><p><strong>Regression coverage:</strong> <code>tests/js/web-controls-contract.test.js</code> verifies generated IDs, field association and safe cleanup.</p><p><strong>Verification boundary:</strong> real screen-reader announcement and focus order still require browser/assistive-technology verification.</p><h2 id="visual-and-interaction-assessment" tabindex="-1">Visual and interaction assessment <a class="header-anchor" href="#visual-and-interaction-assessment" aria-label="Permalink to “Visual and interaction assessment”">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to “Positive”">​</a></h3><ul><li>The form uses semantic labels, real buttons/links, headings and a clear primary action.</li><li>The account editor uses a radio control for the consolidation account and visually marks the selected card.</li><li>Specific cash-flow dates use a bounded date input with removable date chips.</li><li>The layout has desktop/tablet/mobile breakpoints, collapses the navigation rail on smaller screens, and uses larger mobile control sizes.</li><li>Focus-visible styling, touch-target sizing and reduced-motion CSS are present.</li><li>The recent visual-restraint pass reduced redundant numbering, decorative labels, heavy gradients and excessive pill/container treatments while preserving meaningful financial warnings and states.</li><li>Simulation status is exposed with a live status region and elapsed time.</li></ul><h3 id="gaps-requiring-rendered-qa" tabindex="-1">Gaps requiring rendered QA <a class="header-anchor" href="#gaps-requiring-rendered-qa" aria-label="Permalink to “Gaps requiring rendered QA”">​</a></h3><ul><li>No browser screenshot comparison or automated visual-regression suite was found in the repository tests.</li><li>Contrast has not been measured against WCAG 2.2 AA thresholds; token usage alone does not prove contrast.</li><li>Screen-reader announcement order, keyboard-only operation, browser zoom at 200–400%, and small viewport overflow were not manually verified.</li><li>UI-01/02/03 implementation fixes are present on the working branch; full accessibility QA still requires real-browser, keyboard, touch and screen-reader verification.</li><li>Desktop/mobile layout and all meaningful states should be checked in the new dev preview once deployment succeeds.</li></ul><h2 id="required-manual-state-matrix" tabindex="-1">Required manual state matrix <a class="header-anchor" href="#required-manual-state-matrix" aria-label="Permalink to “Required manual state matrix”">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>States to inspect</th></tr></thead><tbody><tr><td>Catalogue</td><td>loading, loaded, empty/unavailable, one bank with no rate data</td></tr><tr><td>Accounts</td><td>one account, many accounts, primary change, remove last account, imported unusual IDs</td></tr><tr><td>Cash flows</td><td>recurring/scheduled, long names, invalid date, outside-period date, strict/defer/best-effort</td></tr><tr><td>Strategy</td><td>Greedy, GSS, Absolute R+, setting panel transitions, decision cap reached</td></tr><tr><td>Simulation</td><td>preparing, running, edit while running, success, failure, reuse, superseded/cancelled</td></tr><tr><td>Results</td><td>no bookings, many bookings, outstanding outflows, large numbers, long labels</td></tr><tr><td>Motion</td><td>normal, reduced motion, keyboard, touch, interrupted transitions</td></tr><tr><td>Viewports</td><td>320px, 375px, 620px, 850px, 1280px and browser zoom</td></tr></tbody></table><h2 id="design-system-assessment" tabindex="-1">Design-system assessment <a class="header-anchor" href="#design-system-assessment" aria-label="Permalink to “Design-system assessment”">​</a></h2><p>The web UI has a coherent dark token-based palette and a restrained component language after the recent visual pass. Avoid another broad visual redesign. The next UI pass should prioritize functional clarity, error association, real-device inspection and contrast measurement rather than additional styling.</p>`,24)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};